import bpy
ns=bpy.app.driver_namespace['harbor_layout_study']
exec(r'''
group=bpy.data.collections['Layout_western_land'];group.hide_viewport=False;group.hide_render=False
for o in list(group.objects):
 if o.name=='western coastal shelf':bpy.data.objects.remove(o,do_unlink=True)
# Longer coastline with a short sandy neck meeting the pirate islet;
# frame edges should not bias the open-sea/land comparison.
vs=[];n=55
for band in range(4):
 for j in range(n):
  z=-65+j*2.5;neck=2.6*math.exp(-((z+8.2)/3.5)**2);edge=-18.1+1.4*math.sin(z*.12)+neck
  x=edge+[-1.1,0,-3.2,-18.0][band];y=[-2.5,.10,.9,2.0][band];vs.append((x,y,z))
fs=[]
for band in range(3):
 for j in range(n-1):fs.append((band*n+j,band*n+j+1,(band+1)*n+j+1,(band+1)*n+j))
o=mesh('western coastal shelf',vs,fs,'sand');o.data.materials.append(mats['grass'])
for p in o.data.polygons:p.material_index=int(p.index>=(n-1)*2)
export('western_land');bpy.ops.wm.save_as_mainfile(filepath=bpy.data.filepath)
print('WESTERN_COMPARISON_EXTENDED')
''',ns)
